function addReviewedRoleMatchups(candidate, enemy, reviewedRoles, answerSlot, threatSlot, plan, why, play, risk, runeWhy, options = {}) {
  for (const role of reviewedRoles) {
    const rule = researchedCounter(candidate, enemy, role, answerSlot, threatSlot, plan, why, play, risk, runeWhy, { priority: 2, ...options });
    if (counterMatchupRules.some((entry) => entry.id === rule.id)) throw new Error(`Duplicate researched matchup ${rule.id}`);
    counterMatchupRules.push(rule);
  }
}

